barrett_ct.v.source:
// barrett_ct — CONSTANT-TIME Barrett modular reduction for Kyber / ML-KEM (q = 3329). This is the REAL,
// value-correct Barrett reduce (the same construction as the reference `barrett_reduce`), not a placeholder:
//
//     t = round(v * a / 2^K)  with  v = round(2^K / q) = 20159, K = 26   (the canonical Kyber constants)
//     r = a - t*q             then a single branch-free conditional +q / -q to land r in [0, q).
//
// This computes r == a mod 3329 for every 16-bit coefficient `a`. That functional correctness is now PROVEN,
// not asserted: a separate functional-equivalence proof establishes the combinational r-cone bit-exact to the public spec
// `r = a % 3329` over ALL 2^16 inputs, and
// `make bv-decide-barrett` KERNEL-checks it with Lean `bv_decide` (a buggy K=25 twin is refused). [An earlier
// comment here claimed an "iverilog TB / tools" exhaustive check that never existed; WS-B replaces that stale
// assertion with the real, stronger proof.]
// It is a genuine multiply-shift Barrett (recognizable PQC datapath: a 15x16 multiplier by the constant v, a
// K-bit right shift, a t*q multiply, a subtract, and branch-free correction), NOT a repeated conditional
// subtract. The reduction value depends on the operand (that IS the reduction); its TIMING does not.
//
// The completion signal `done = running & (cnt == W)` asserts after EXACTLY W cycles regardless of the secret
// coefficient `a` — a data-oblivious cycle counter. The datapath (multiplier / shift / correction) is
// operand-dependent in VALUE but the counter that gates `done` never sees `a`, so the reduction's *timing* is
// constant. The constant-time property here is over this completion / cycle channel — exactly as for
// the picorv32 divider and the modexp core — and is NOT a claim about datapath-value obliviousness, power, EM,
// or cache. (A fixed-latency Barrett is already straight-line; the load-bearing content is that it is a
// recognizable PQC core and that the leaky twin below is a genuine, correctly-refused timing leak.)
//
// The leaky counterpart `barrett_leaky.v` normalizes by a data-dependent repeated-subtraction loop, so its
// `done` timing leaks the coefficient magnitude — and the self-composition CT proof correctly REFUSES it.
module barrett_ct (clk, rst, start, a, done, r);
    parameter  AW = 16;                     // Kyber Barrett operates on 16-bit values (canonical barrett_reduce)
    parameter  DW = 12;                     // q = 3329 < 2^12
    parameter  W  = 8;                      // FIXED, data-OBLIVIOUS completion latency
    localparam integer   V = 20159;         // v = round(2^26 / q) — the canonical Kyber Barrett constant
    localparam integer   K = 26;            // Barrett shift
    localparam [16:0]    Q = 17'd3329;      // Kyber prime

    input                clk, rst, start;
    input  [AW-1:0]      a;                 // SECRET coefficient (product) to reduce mod q
    output               done;
    output [DW-1:0]      r;

    reg [AW-1:0] a_reg;                     // registered operand (feeds only the value datapath, never `done`)
    reg [3:0]    cnt;                       // cycle counter (W <= 15) — data-OBLIVIOUS
    reg          running;

    assign done = running & (cnt == W);     // operand-free completion: fires after EXACTLY W cycles

    // Canonical branch-free Barrett reduction over the registered operand.
    wire [30:0]        prod = V * a_reg;                                        // v * a
    wire [12:0]        t    = (prod + (1 << (K-1))) >> K;                        // round(v*a / 2^K) ~ round(a/q)
    wire [16:0]        tq   = t * Q;                                            // t * q
    wire signed [17:0] sub  = $signed({2'b00, a_reg}) - $signed({1'b0, tq});    // a - t*q  (centered rep)
    wire signed [17:0] cadd = sub[17]              ? (sub  + $signed({1'b0, Q})) : sub;   // +q if negative
    wire signed [17:0] csub = (cadd >= $signed({1'b0, Q})) ? (cadd - $signed({1'b0, Q})) : cadd; // safety -q
    assign r = csub[DW-1:0];               // r = a mod q, in [0, q)

    always @(posedge clk) begin
        if (rst) begin
            a_reg <= 0; cnt <= 4'd0; running <= 1'b0;
        end else if (start) begin
            a_reg <= a; cnt <= 4'd0; running <= 1'b1;          // load secret operand, begin
        end else if (running & (cnt != W)) begin
            cnt <= cnt + 4'd1;                                 // the ONLY thing gating `done` — a plain counter
        end
    end
endmodule

barrett_leaky.v.source:
// barrett_leaky — the NON-constant-time counterpart of `barrett_ct`: a naive "reduce by repeated subtraction"
// normalization that LOOPS `acc -= Q` until `acc < Q`. This is a real, tempting implementation (no multiplier,
// tiny area — a common way people "just reduce mod q") but the NUMBER of iterations, hence the completion cycle
// `done`, depends on the SECRET coefficient's magnitude, leaking it through timing. This is the Kyber/Barrett
// analog of the leaky Euclidean GCD and the leaky modexp early-exit: the self-composition constant-time proof
// MUST refuse it, because `done`'s fan-in cone now contains the secret coefficient register `acc`.
module barrett_leaky (clk, rst, start, a, done, r);
    parameter AW = 16;                      // same 16-bit interface as barrett_ct (safe-vs-leaky twin)
    parameter DW = 12;
    input                clk, rst, start;
    input  [AW-1:0]      a;                 // SECRET input to reduce mod q
    output               done;
    output [DW-1:0]      r;

    localparam [AW-1:0] Q = 16'd3329;       // Kyber prime
    reg [AW-1:0]   acc;
    reg            running;

    // LEAK: `(acc < Q)` folds the SECRET coefficient register into the completion condition -> `done` timing
    // depends on how many subtractions were needed -> NOT constant-time. (Compare barrett_ct's `cnt == W`.)
    assign done = running & (acc < Q);
    assign r    = acc[DW-1:0];

    always @(posedge clk) begin
        if (rst) begin
            acc <= 0; running <= 1'b0;
        end else if (start) begin
            acc <= a; running <= 1'b1;                       // load secret operand, begin
        end else if (running & ~(acc < Q)) begin
            acc <= acc - Q;                                  // repeated subtraction: iteration count leaks `a`
        end
    end
endmodule

barrett_buggy.v.source:
// barrett_buggy — a BUGGY Barrett reduction (the WS-B teeth): identical to `barrett_ct.v` except the Barrett
// SHIFT is WRONG (K = 25 instead of the canonical 26). The reciprocal constant V = round(2^26/3329) is
// calibrated for a 2^26 shift; using 2^25 scales the quotient estimate `t` by ~2x, an error far outside what
// the single +q/-q correction can absorb, so `r != a mod 3329` on the majority of coefficients (62206 / 65536).
// The equivalence miter against `barrett_spec` is then SATISFIABLE — a refutation over the input domain exists —
// and the method REFUSES to certify it. A timing check correctly does NOT flag it, which is what makes
// this fixture an out-of-remit control.
//
// (A subtler off-by-one in V — e.g. 20158 or even 20000 — is NOT used here: Barrett's ±q correction absorbs
// small reciprocal errors, so those variants are STILL bit-exact over the 16-bit domain and would be a
// strawman "bug" that actually passes. K=25 is a genuine, unabsorbable miscalibration. The completion channel
// is unchanged, so this twin is still CONSTANT-TIME — the bug is purely in the VALUE, isolating the
// functional-correctness proof from the timing proof: CT alone would accept this buggy core.)
module barrett_buggy (clk, rst, start, a, done, r);
    parameter  AW = 16;
    parameter  DW = 12;
    parameter  W  = 8;
    localparam integer   V = 20159;         // canonical reciprocal — calibrated for a 2^26 shift
    localparam integer   K = 25;            // BUG: should be 26; the shift no longer matches V -> t is ~2x off
    localparam [16:0]    Q = 17'd3329;

    input                clk, rst, start;
    input  [AW-1:0]      a;
    output               done;
    output [DW-1:0]      r;

    reg [AW-1:0] a_reg;
    reg [3:0]    cnt;
    reg          running;

    assign done = running & (cnt == W);

    wire [30:0]        prod = V * a_reg;
    wire [12:0]        t    = (prod + (1 << (K-1))) >> K;
    wire [16:0]        tq   = t * Q;
    wire signed [17:0] sub  = $signed({2'b00, a_reg}) - $signed({1'b0, tq});
    wire signed [17:0] cadd = sub[17]              ? (sub  + $signed({1'b0, Q})) : sub;
    wire signed [17:0] csub = (cadd >= $signed({1'b0, Q})) ? (cadd - $signed({1'b0, Q})) : cadd;
    assign r = csub[DW-1:0];

    always @(posedge clk) begin
        if (rst) begin
            a_reg <= 0; cnt <= 4'd0; running <= 1'b0;
        end else if (start) begin
            a_reg <= a; cnt <= 4'd0; running <= 1'b1;
        end else if (running & (cnt != W)) begin
            cnt <= cnt + 4'd1;
        end
    end
endmodule

ct_cmp.v.source:
// ct_cmp — CONSTANT-TIME equality/compare that ALWAYS scans all W bits (the memcmp-hardening pattern used
// against timing side channels in MAC/tag comparison). It accumulates a difference flag every cycle but never
// exits early, so `done = running & (cnt == W)` is a data-oblivious counter — completion timing is independent
// of WHERE (or whether) the operands differ. Teeth: `cmp_leaky.v` early-exits on the first differing bit, so
// its `done` timing leaks the first-mismatch position (the classic non-constant-time memcmp).
module ct_cmp (clk, rst, start, x, y, done, equal);
    parameter W = 8;
    input          clk, rst, start;
    input  [W-1:0] x, y;                   // SECRET operands (e.g. computed tag vs expected tag)
    output         done;
    output         equal;

    reg [W-1:0] xr, yr;
    reg         diff;
    reg [3:0]   cnt;                        // data-OBLIVIOUS cycle counter
    reg         running;

    assign done  = running & (cnt == W);    // operand-free completion: always W cycles
    assign equal = ~diff;

    always @(posedge clk) begin
        if (rst) begin
            xr <= 0; yr <= 0; diff <= 1'b0; cnt <= 4'd0; running <= 1'b0;
        end else if (start) begin
            xr <= x; yr <= y; diff <= 1'b0; cnt <= 4'd0; running <= 1'b1;
        end else if (running & (cnt != W)) begin
            diff <= diff | (xr[0] ^ yr[0]);   // accumulate difference — NEVER exits early
            xr   <= xr >> 1;
            yr   <= yr >> 1;
            cnt  <= cnt + 4'd1;               // the ONLY thing gating `done`
        end
    end
endmodule

cmp_leaky.v.source:
// cmp_leaky — the LEAKY counterpart of `ct_cmp`: the classic early-exit memcmp that stops at the first
// differing bit, so `done` timing leaks the position of the first mismatch (a textbook tag/MAC timing oracle).
// Its completion cone contains operand bits, so no operand-free inductive invariant exists and the
// self-composition proof correctly REFUSES to certify constant-time.
module cmp_leaky (clk, rst, start, x, y, done, equal);
    parameter W = 8;
    input          clk, rst, start;
    input  [W-1:0] x, y;                   // SECRET operands
    output         done;
    output         equal;

    reg [W-1:0] xr, yr;
    reg         diff;
    reg         running;

    // LEAK: completion fires early once a mismatch is seen OR all bits consumed -> operand-dependent timing
    assign done  = running & (diff | (xr == 0 && yr == 0));
    assign equal = ~diff;

    always @(posedge clk) begin
        if (rst) begin
            xr <= 0; yr <= 0; diff <= 1'b0; running <= 1'b0;
        end else if (start) begin
            xr <= x; yr <= y; diff <= 1'b0; running <= 1'b1;
        end else if (running & ~diff & (xr != 0 || yr != 0)) begin
            diff <= (xr[0] ^ yr[0]);          // exits early on first mismatch -> variable timing
            xr   <= xr >> 1;
            yr   <= yr >> 1;
        end
    end
endmodule

ct_div_wide.v.source:
// ct_div_wide — a parameterized CONSTANT-TIME restoring divider with wipe-on-done, in clean RTL.
//
// Purpose (SCALE demonstration): the completion signal `done` is a pure function of the iteration COUNTER
// (cnt == W), never of the operand data — so the divider runs EXACTLY W fixed cycles regardless of a/b, i.e.
// it is constant-time by construction (the same reason picorv32_pcpi_div is CT). The datapath (the W-bit
// shift/compare/subtract) grows ~O(W) — quadratically in area for the comparator chain — while the completion
// cone (the counter FSM) grows only ~log2(W). So bumping WIDTH 32 -> 256 makes the design ~10x in gates but
// leaves the localized completion-observable cone essentially unchanged. This is the clean-RTL twin of
// pcpi_div_wiped: the completion cone stays small even as the datapath grows.
//
// Secret operands: a, b (the dividend/divisor). Completion: done. Result: q (quotient), r (remainder).
// Wipe-on-done: on the completion cycle the operand-derived scratch (rem_reg, a_shift) is zeroed, so no operand
// residue survives past `done` (the no-secret-residue property, matching pcpi_div_wiped's wipe).
//
// CONSTANT-TIME CLAIM (the property proven): `done` and the cycle on which it asserts are independent of a,b.
// (A leaky twin that early-exits when the remainder hits zero would make `done` data-dependent and be REFUSED.)

module ct_div_wide #(
	parameter WIDTH = 256
) (
	input                    clk,
	input                    resetn,
	input                    start,        // pulse: latch a,b and begin
	input      [WIDTH-1:0]   a,            // dividend (SECRET)
	input      [WIDTH-1:0]   b,            // divisor  (SECRET)
	output reg               done,         // completion (data-OBLIVIOUS: a pure function of cnt)
	output reg [WIDTH-1:0]   q,            // quotient
	output reg [WIDTH-1:0]   r             // remainder
);
	localparam CW = $clog2(WIDTH) + 1;     // counter width

	reg [CW-1:0]        cnt;               // iteration counter — the ONLY thing `done` depends on
	reg                 running;
	reg [WIDTH-1:0]     rem_reg;           // running remainder (operand-derived scratch)
	reg [WIDTH-1:0]     a_shift;           // dividend being shifted in (operand-derived scratch)
	reg [WIDTH-1:0]     b_reg;             // divisor latch
	reg [WIDTH-1:0]     q_reg;             // quotient accumulator

	// one restoring-division step: shift remainder in the next dividend bit, trial-subtract the divisor.
	wire [WIDTH-1:0] rem_shifted = {rem_reg[WIDTH-2:0], a_shift[WIDTH-1]};
	wire             ge          = (rem_shifted >= b_reg);
	wire [WIDTH-1:0] rem_next    = ge ? (rem_shifted - b_reg) : rem_shifted;

	// completion is a PURE function of the counter — this is what makes the divider constant-time.
	wire done_now = running && (cnt == WIDTH[CW-1:0]);

	always @(posedge clk) begin
		if (!resetn) begin
			cnt     <= 0;
			running <= 0;
			done    <= 0;
			rem_reg <= 0;
			a_shift <= 0;
			b_reg   <= 0;
			q_reg   <= 0;
			q       <= 0;
			r       <= 0;
		end else begin
			done <= 0;
			if (start && !running) begin
				running <= 1;
				cnt     <= 0;
				rem_reg <= 0;
				a_shift <= a;
				b_reg   <= b;
				q_reg   <= 0;
			end else if (running) begin
				if (done_now) begin
					// completion cycle: latch result, WIPE operand-derived scratch (no residue survives `done`).
					running <= 0;
					done    <= 1;
					q       <= q_reg;
					r       <= rem_reg;
					rem_reg <= 0;      // wipe
					a_shift <= 0;      // wipe
				end else begin
					cnt     <= cnt + 1;
					rem_reg <= rem_next;
					a_shift <= {a_shift[WIDTH-2:0], 1'b0};
					q_reg   <= {q_reg[WIDTH-2:0], ge};
				end
			end
		end
	end
endmodule

ct_div_leaky.v.source:
// ct_div_leaky — the LEAKY TWIN of ct_div_wide (the teeth for the constant-time scaling proof).
//
// IDENTICAL to ct_div_wide EXCEPT the completion `done_now` also fires on an EARLY-EXIT when the running
// remainder reaches zero (`rem_reg == 0`). That makes the completion cycle DATA-DEPENDENT: for operands whose
// division terminates early, `done` asserts sooner — a genuine constant-time VIOLATION (a timing side channel).
//
// Expected: the CT self-composition miter is SAT (a distinguishing operand pair exists) ⇒ this twin is REFUSED,
// AND its completion cone structurally touches the operand-derived `rem_reg` ⇒ `operand_free == False`. This is
// the non-vacuity witness: the CT check distinguishes ct_div_wide (PROVES) from ct_div_leaky (REFUSED).

module ct_div_leaky #(
	parameter WIDTH = 256
) (
	input                    clk,
	input                    resetn,
	input                    start,
	input      [WIDTH-1:0]   a,
	input      [WIDTH-1:0]   b,
	output reg               done,
	output reg [WIDTH-1:0]   q,
	output reg [WIDTH-1:0]   r
);
	localparam CW = $clog2(WIDTH) + 1;

	reg [CW-1:0]        cnt;
	reg                 running;
	reg [WIDTH-1:0]     rem_reg;
	reg [WIDTH-1:0]     a_shift;
	reg [WIDTH-1:0]     b_reg;
	reg [WIDTH-1:0]     q_reg;

	wire [WIDTH-1:0] rem_shifted = {rem_reg[WIDTH-2:0], a_shift[WIDTH-1]};
	wire             ge          = (rem_shifted >= b_reg);
	wire [WIDTH-1:0] rem_next    = ge ? (rem_shifted - b_reg) : rem_shifted;

	// LEAK: completion also fires early when the remainder is exhausted — DATA-DEPENDENT timing.
	wire done_now = running && ((cnt == WIDTH[CW-1:0]) || (rem_reg == 0 && cnt != 0));

	always @(posedge clk) begin
		if (!resetn) begin
			cnt <= 0; running <= 0; done <= 0; rem_reg <= 0; a_shift <= 0; b_reg <= 0; q_reg <= 0; q <= 0; r <= 0;
		end else begin
			done <= 0;
			if (start && !running) begin
				running <= 1; cnt <= 0; rem_reg <= 0; a_shift <= a; b_reg <= b; q_reg <= 0;
			end else if (running) begin
				if (done_now) begin
					running <= 0; done <= 1; q <= q_reg; r <= rem_reg; rem_reg <= 0; a_shift <= 0;
				end else begin
					cnt <= cnt + 1; rem_reg <= rem_next; a_shift <= {a_shift[WIDTH-2:0], 1'b0}; q_reg <= {q_reg[WIDTH-2:0], ge};
				end
			end
		end
	end
endmodule

ct_gcd.v.source:
// ct_gcd — fixed-iteration (constant-time) GCD. `done` is a function ONLY of a cycle counter `iter`
// that advances unconditionally while running, so completion time is FIXED (K cycles) regardless of the
// secret operands — i.e. the timing observable is data-oblivious. The datapath still reduces the secret
// operands into `gcd_out` (so the property is NON-vacuous: the secret flows to the result, just not to
// the timing). This is the positive design: self-composition PROVES timing non-interference, and the
// refutation is independently re-checked.
//
// Interface mirrors the self-composition transition relation for the `ct_gcd` benchmark.
module ct_gcd (clk, rst, start, a_in, b_in, done, gcd_out);
    parameter K = 5'd16;                 // fixed number of reduction cycles

    input             clk, rst, start;
    input      [7:0]  a_in, b_in;        // SECRET operands
    output            done;
    output     [7:0]  gcd_out;

    reg  [7:0] a, b;
    reg  [4:0] iter;
    reg        running;

    // done depends ONLY on `iter` and `running` (control), never on a/b (secret) -> constant time.
    assign done    = running & (iter == K);
    assign gcd_out = a;

    always @(posedge clk) begin
        if (rst) begin
            a <= 8'd0; b <= 8'd0; iter <= 5'd0; running <= 1'b0;
        end else if (start) begin
            a <= a_in; b <= b_in; iter <= 5'd0; running <= 1'b1;
        end else if (running & (iter < K)) begin
            // one reduction step, ALWAYS executed (constant-time): the branch affects the DATA, not
            // whether we step, so `iter` (and thus `done`) is independent of the operands.
            if      (a >= b && b != 8'd0) a <= a - b;
            else if (b >  a && a != 8'd0) b <= b - a;
            iter <= iter + 5'd1;
        end
    end
endmodule

euclid_gcd.v.source:
// euclid_gcd — subtractive Euclidean GCD. The canonical NON-constant-time datapath: the number of
// reduction steps (hence the cycle at which `done` asserts) depends on the SECRET operands, so the
// completion time leaks operand structure. This is the negative / found-bug design: a self-composition
// proof of timing non-interference FAILS on it, and iverilog reproduces a distinguishing secret pair.
//
// Interface mirrors the self-composition transition relation for the `euclid_gcd` benchmark.
module euclid_gcd (clk, rst, start, a_in, b_in, done, gcd_out);
    input             clk, rst, start;
    input      [7:0]  a_in, b_in;      // SECRET operands (assumed non-zero)
    output            done;
    output     [7:0]  gcd_out;

    reg  [7:0] a, b;
    reg        running;

    wire eq = (a == b);
    assign done    = running & eq;      // asserts when the algorithm converges (a==b==gcd)
    assign gcd_out = a;

    always @(posedge clk) begin
        if (rst) begin
            a <= 8'd0; b <= 8'd0; running <= 1'b0;
        end else if (start) begin
            a <= a_in; b <= b_in; running <= 1'b1;   // load operands, begin
        end else if (running & ~eq) begin
            if (a > b) a <= a - b;                    // secret-dependent control -> variable latency
            else       b <= b - a;
        end
    end
endmodule

euclid_gcd_repaired.v.source:
// euclid_gcd_repaired — the CERTIFIED REPAIR of `euclid_gcd.v` (WS-C). Generated by applying ONE known
// countermeasure class (fixed-trip-count / data-oblivious control) to the leaky design, in response to its
// timing-leak counterexample. This is NOT a hand-written ct_gcd: it PRESERVES euclid's own subtractive
// reduction step (`if a>b: a-=b; else if b>a: b-=a`) as its identity, and only rewrites the CONTROL:
//
//   leak:   assign done = running & (a == b);            // completion depends on the SECRET operands
//   repair: assign done = running & (iter == K);         // completion depends only on a control counter
//
// plus a `iter` counter that advances unconditionally while running, and the reduction step now runs every
// cycle (its branch affects the DATA, never whether we step). The completion cone is therefore operand-free,
// so the gate-level self-composition k-induction PROVES constant-time with an AUTO-DISCOVERED invariant
// (no human supplies it) — see `make ct-repair`. The secret still flows into `gcd_out`, so the property is
// non-vacuous (secret -> result, just not -> timing).
module euclid_gcd_repaired (clk, rst, start, a_in, b_in, done, gcd_out);
    parameter K = 5'd16;                 // fixed completion horizon (>= worst-case 8-bit reduction depth)

    input             clk, rst, start;
    input      [7:0]  a_in, b_in;        // SECRET operands
    output            done;
    output     [7:0]  gcd_out;

    reg  [7:0] a, b;
    reg  [4:0] iter;
    reg        running;

    // COUNTERMEASURE: `done` is a function ONLY of the control counter `iter` and `running`, never of the
    // secret-dependent `(a == b)` predicate the leaky design used.
    assign done    = running & (iter == K);
    assign gcd_out = a;

    always @(posedge clk) begin
        if (rst) begin
            a <= 8'd0; b <= 8'd0; iter <= 5'd0; running <= 1'b0;
        end else if (start) begin
            a <= a_in; b <= b_in; iter <= 5'd0; running <= 1'b1;
        end else if (running & (iter < K)) begin
            // euclid's OWN subtractive reduction step, now executed unconditionally each cycle. Once a==b the
            // branch simply holds a,b (neither guard fires), so timing stays fixed at K regardless of secrets.
            if      (a > b) a <= a - b;
            else if (b > a) b <= b - a;
            iter <= iter + 5'd1;
        end
    end
endmodule

ct_modmul.v.source:
// ct_modmul — CONSTANT-TIME double-and-add modular multiplication `a*b mod m` (a building block of RSA/ECC
// scalar routines). Every cycle it doubles the accumulator and conditionally adds `a`, with a conditional
// modular reduction — but the multiplier bit only SELECTS values; it never gates control. Completion
// `done = running & (cnt == W)` is a data-oblivious counter, so the timing is constant-time. Teeth:
// `modmul_leaky.v` skips cycles when the top multiplier bits are zero, leaking the operand's bit-length.
module ct_modmul (clk, rst, start, a, b, m, done, result);
    parameter W = 8;
    input            clk, rst, start;
    input  [W-1:0]   a, b, m;              // SECRET operands a,b (m the modulus)
    output           done;
    output [W-1:0]   result;

    reg [W:0]   acc;                        // one guard bit for the add/reduce
    reg [W-1:0] ar, br, mr;
    reg [3:0]   cnt;                        // data-OBLIVIOUS cycle counter
    reg         running;

    assign done   = running & (cnt == W);   // operand-free completion: exactly W cycles
    assign result = acc[W-1:0];

    always @(posedge clk) begin
        if (rst) begin
            acc <= 0; ar <= 0; br <= 0; mr <= 0; cnt <= 4'd0; running <= 1'b0;
        end else if (start) begin
            acc <= 0; ar <= a; br <= b; mr <= m; cnt <= 4'd0; running <= 1'b1;
        end else if (running & (cnt != W)) begin
            // process one multiplier bit (MSB-first double-and-add), always-select, never branch on control
            acc <= (({acc[W-1:0], 1'b0}) + (br[W-1] ? {1'b0, ar} : 0));  // double + conditional add (value-select)
            br  <= br << 1;
            cnt <= cnt + 4'd1;               // the ONLY thing gating `done`
        end
    end
endmodule

