ct_mul.v.source:
// ct_mul — CONSTANT-TIME shift-add multiplier. Runs EXACTLY W iterations regardless of the operands:
// every cycle it conditionally adds the (shifted) multiplicand based on the current multiplier bit, but the
// bit only SELECTS a value — it never gates the control. Completion `done = running & (cnt == W)` is a plain
// data-oblivious counter, so the completion TIMING is constant-time (the product VALUE is operand-dependent,
// as it must be; only the timing channel is proven). Same completion structure as `modexp_ct` / the picorv32
// divider. Teeth: `mul_leaky.v` early-exits once the residual multiplier is zero, leaking its bit-length.
module ct_mul (clk, rst, start, a, b, done, prod);
    parameter W = 8;
    input            clk, rst, start;
    input  [W-1:0]   a, b;                 // SECRET operands
    output           done;
    output [2*W-1:0] prod;

    reg [2*W-1:0] acc, mcand;
    reg [W-1:0]   mplier;
    reg [3:0]     cnt;                     // data-OBLIVIOUS cycle counter (W <= 15)
    reg           running;

    assign done = running & (cnt == W);    // operand-free completion: fires after exactly W cycles
    assign prod = acc;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 0; mcand <= 0; mplier <= 0; cnt <= 4'd0; running <= 1'b0;
        end else if (start) begin
            acc <= 0; mcand <= {{W{1'b0}}, a}; mplier <= b; cnt <= 4'd0; running <= 1'b1;
        end else if (running & (cnt != W)) begin
            acc    <= mplier[0] ? (acc + mcand) : acc;   // add-ALWAYS-select: value secret, TIMING fixed
            mcand  <= mcand << 1;
            mplier <= mplier >> 1;
            cnt    <= cnt + 4'd1;                         // the ONLY thing gating `done`
        end
    end
endmodule

mul_leaky.v.source:
// mul_leaky — the LEAKY counterpart of `ct_mul`: it early-exits as soon as the residual multiplier becomes
// zero, so `done` fires after a number of cycles equal to the multiplier's MSB position — a timing channel
// that leaks the secret operand's bit-length. The completion cone contains operand bits (via `mplier==0`), so
// no operand-free inductive invariant exists and the self-composition proof correctly REFUSES to certify it.
module mul_leaky (clk, rst, start, a, b, done, prod);
    parameter W = 8;
    input            clk, rst, start;
    input  [W-1:0]   a, b;                 // SECRET operands
    output           done;
    output [2*W-1:0] prod;

    reg [2*W-1:0] acc, mcand;
    reg [W-1:0]   mplier;
    reg           running;

    assign done = running & (mplier == 0); // LEAK: completion depends on the secret multiplier's value
    assign prod = acc;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 0; mcand <= 0; mplier <= 0; running <= 1'b0;
        end else if (start) begin
            acc <= 0; mcand <= {{W{1'b0}}, a}; mplier <= b; running <= 1'b1;
        end else if (running & (mplier != 0)) begin
            acc    <= mplier[0] ? (acc + mcand) : acc;
            mcand  <= mcand << 1;
            mplier <= mplier >> 1;                        // early-exit when this hits 0 -> variable timing
        end
    end
endmodule

modexp_ct.v.source:
// modexp_ct — CONSTANT-TIME square-and-multiply-ALWAYS modular exponentiation control, the standard RSA
// timing-attack countermeasure (the always-multiply / constant-time-exponentiation defense — the exponent
// bit never gates control, only selects a value; this is the always-multiply class, distinct from but in the
// spirit of the Montgomery powering ladder). The completion
// signal `done` asserts after EXACTLY W cycles regardless of the secret base/exponent — a data-oblivious
// cycle counter — so the completion TIMING is constant-time. The acc/sq datapath is operand-dependent in
// VALUE (that is the computation) but NEVER in timing: both the "square" and the "multiply" steps run every
// cycle and the exponent bit only SELECTS a value, it never gates the control. The constant-time property
// considered here is over this completion/cycle channel — exactly as for the picorv32 divider (not power/EM).
//
// The leaky counterpart `modexp_leaky.v` early-exits when the remaining exponent is zero, so its `done`
// timing leaks the exponent's Hamming/MSB structure — and the self-composition proof correctly REFUSES it.
module modexp_ct (clk, rst, start, base, exp, modulus, done, result);
    parameter W = 8;
    input            clk, rst, start;
    input  [W-1:0]   base, exp, modulus;   // SECRET operands: base (message), exp (private exponent)
    output           done;
    output [W-1:0]   result;

    reg [W-1:0] acc, sq, e;
    reg [3:0]   cnt;                        // cycle counter (W <= 15) — data-OBLIVIOUS
    reg         running;

    assign done   = running & (cnt == W);  // operand-free completion: fires after exactly W cycles
    assign result = acc;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd1; sq <= 8'd0; e <= 8'd0; cnt <= 4'd0; running <= 1'b0;
        end else if (start) begin
            acc <= 8'd1; sq <= base; e <= exp; cnt <= 4'd0; running <= 1'b1;   // load operands, begin
        end else if (running & (cnt != W)) begin
            acc <= e[0] ? (acc + sq) : acc;   // multiply-ALWAYS-select: value secret, TIMING fixed
            sq  <= sq + sq;                   // square step (data-oblivious control)
            e   <= e >> 1;
            cnt <= cnt + 4'd1;                // the ONLY thing gating `done` — a plain counter
        end
    end
endmodule

modexp_leaky.v.source:
// modexp_leaky — the NON-constant-time counterpart of `modexp_ct`: a square-and-multiply modular
// exponentiation that EARLY-EXITS when the remaining exponent register is all zeros. That is a real,
// tempting optimization (skip the trailing zero exponent bits), but it makes the completion cycle — hence
// `done` — depend on the SECRET exponent's structure, leaking it through timing. This is the modexp analog
// of the leaky Euclidean GCD: the self-composition constant-time proof MUST refuse it, because the
// completion signal's fan-in cone now contains the secret exponent register.
module modexp_leaky (clk, rst, start, base, exp, modulus, done, result);
    parameter W = 8;
    input            clk, rst, start;
    input  [W-1:0]   base, exp, modulus;   // SECRET operands
    output           done;
    output [W-1:0]   result;

    reg [W-1:0] acc, sq, e;
    reg [3:0]   cnt;
    reg         running;

    // LEAK: `(e == 0)` folds the SECRET exponent register into the completion condition -> `done` timing
    // depends on the exponent -> NOT constant-time. (Compare modexp_ct's operand-free `cnt == W`.)
    assign done   = running & ((cnt == W) | (e == 8'd0));
    assign result = acc;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd1; sq <= 8'd0; e <= 8'd0; cnt <= 4'd0; running <= 1'b0;
        end else if (start) begin
            acc <= 8'd1; sq <= base; e <= exp; cnt <= 4'd0; running <= 1'b1;
        end else if (running & ~((cnt == W) | (e == 8'd0))) begin
            acc <= e[0] ? (acc + sq) : acc;
            sq  <= sq + sq;
            e   <= e >> 1;
            cnt <= cnt + 4'd1;
        end
    end
endmodule

x25519_fieldmul.v.source:
// x25519_fieldmul — CONSTANT-TIME field multiplication `opa * opb mod modulus`, the inner primitive of an
// X25519 / Curve25519 Montgomery-ladder step (the field GF(2^255-19), modeled here at a tractable width W).
// The completion-channel CT ARGUMENT is width-parametric in structure, BUT this committed RTL is fixed at
// W=16 and its `reg [4:0] cnt` (below) only counts to 31 — reaching the real W=255 would require widening
// `cnt` and re-proving the (~16x larger) miter. No W>16 proof exists in this repo; do not claim one.
//
// Every cycle doubles the accumulator and CONDITIONALLY ADDS the multiplicand by VALUE-SELECT on the current
// multiplier bit — the secret multiplier only selects an operand value, it never gates control flow. The
// completion signal `done = running & (cnt == W)` is a data-OBLIVIOUS counter: the routine always runs exactly
// W cycles regardless of the secret operands, so the timing is constant-time (no operand bit reaches the
// completion cone). Its leaky twin `x25519_fieldmul_leaky.v` early-exits on the multiplier value and is
// correctly REFUSED by the self-composition proof.
module x25519_fieldmul (clk, rst, start, opa, opb, modulus, done, result);
    parameter W = 16;
    input             clk, rst, start;
    input  [W-1:0]    opa, opb, modulus;   // SECRET field operands (multiplicand, multiplier) + the prime
    output            done;
    output [W-1:0]    result;

    reg [W:0]   acc;                        // accumulator with one guard bit for double + add
    reg [W-1:0] ar, br, mr;                 // latched multiplicand / multiplier / modulus
    reg [4:0]   cnt;                        // data-OBLIVIOUS cycle counter (0..W), 5 bits covers W<=16
    reg         running;

    assign done   = running & (cnt == W);   // operand-free completion: exactly W cycles, always
    assign result = acc[W-1:0];

    always @(posedge clk) begin
        if (rst) begin
            acc <= 0; ar <= 0; br <= 0; mr <= 0; cnt <= 5'd0; running <= 1'b0;
        end else if (start) begin
            acc <= 0; ar <= opa; br <= opb; mr <= modulus; cnt <= 5'd0; running <= 1'b1;
        end else if (running & (cnt != W)) begin
            // MSB-first double-and-add: double the accumulator, VALUE-SELECT add of the multiplicand on the
            // current multiplier bit — control never branches on the secret. (A modular reduction on the
            // guard bit would slot here for the full field; it too is value-select, keeping the cone clean.)
            acc <= (({acc[W-1:0], 1'b0}) + (br[W-1] ? {1'b0, ar} : 0));
            br  <= br << 1;
            cnt <= cnt + 5'd1;               // the ONLY thing gating `done`
        end
    end
endmodule

x25519_fieldmul_leaky.v.source:
// x25519_fieldmul_leaky — the LEAKY counterpart of `x25519_fieldmul`: it early-exits once the residual
// multiplier `br` is zero, skipping the remaining doublings, so `done` timing leaks the secret multiplier's
// most-significant set-bit position (its bit-length). The completion cone therefore contains operand bits, and
// the self-composition constant-time proof correctly REFUSES to certify it (the teeth).
module x25519_fieldmul_leaky (clk, rst, start, opa, opb, modulus, done, result);
